static u8 busts_block(u8 id, u8 part) {
    const u8 *m = busts_meta + (u16)id * 5;
    u8 w = m[3], h = m[4];
    u8 r0 = (u8)(part * 4), r1 = (u8)(r0 + 4);
    const u8 *t, *a;
    if (r1 > h) r1 = h;
    t = busts_bt[id] + (u16)r0 * w;
    a = busts_ba[id] + (u16)r0 * w;
    if (m[0]) {
        set_win_tiles(m[1], (u8)(m[2] + r0), w, (u8)(r1 - r0), t);
        VBK_REG = 1;
        set_win_tiles(m[1], (u8)(m[2] + r0), w, (u8)(r1 - r0), a);
    } else {
        set_bkg_tiles(m[1], (u8)(m[2] + r0), w, (u8)(r1 - r0), t);
        VBK_REG = 1;
        set_bkg_tiles(m[1], (u8)(m[2] + r0), w, (u8)(r1 - r0), a);
    }
    VBK_REG = 0;
    return r1 < h ? 1 : 0;
}

